import os
import hashlib
import hmac
import time
import secrets
import re
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

# Role hierarchy: higher number = more privilege
ROLE_HIERARCHY = {
    'viewer': 1,
    'editor': 2,
    'manager': 3,
    'admin': 4,
    'superadmin': 5
}

# Simulated user database with bcrypt-style hashes
USERS_DB = {
    'alice': {'password_hash': hashlib.sha256(b'alice_secret_2024').hexdigest(), 'role': 'superadmin', 'tenant': 'corp-a'},
    'bob': {'password_hash': hashlib.sha256(b'bob_password_99').hexdigest(), 'role': 'admin', 'tenant': 'corp-a'},
    'carol': {'password_hash': hashlib.sha256(b'carol_pass_xyz').hexdigest(), 'role': 'manager', 'tenant': 'corp-a'},
    'dave': {'password_hash': hashlib.sha256(b'dave_viewer_pw').hexdigest(), 'role': 'viewer', 'tenant': 'corp-b'},
    'eve': {'password_hash': hashlib.sha256(b'eve_editor_pw').hexdigest(), 'role': 'editor', 'tenant': 'corp-b'},
}

# Session store
ACTIVE_SESSIONS = {}

def constant_time_compare(a, b):
    """Timing-safe string comparison"""
    return hmac.compare_digest(a.encode('utf-8') if isinstance(a, str) else a,
                               b.encode('utf-8') if isinstance(b, str) else b)

def validate_input(value, pattern, max_len=64):
    """Strict input validation"""
    if not value or not isinstance(value, str):
        return False
    if len(value) > max_len:
        return False
    return bool(re.match(pattern, value))

def create_session(username, role, tenant):
    """Create authenticated session with secure token"""
    token = secrets.token_urlsafe(32)
    ACTIVE_SESSIONS[token] = {
        'username': username,
        'role': role,
        'tenant': tenant,
        'created_at': time.time(),
        'last_access': time.time()
    }
    return token

def get_session(token):
    """Retrieve and validate session"""
    session = ACTIVE_SESSIONS.get(token)
    if not session:
        return None
    # Session expiry: 1 hour
    if time.time() - session['created_at'] > 3600:
        del ACTIVE_SESSIONS[token]
        return None
    session['last_access'] = time.time()
    return session

def require_auth(f):
    """Authentication middleware"""
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401
        token = auth_header[7:]
        if not validate_input(token, r'^[A-Za-z0-9_\-]+$', 64):
            return jsonify({'error': 'Invalid token format'}), 401
        session = get_session(token)
        if not session:
            return jsonify({'error': 'Invalid or expired session'}), 401
        g.current_user = session
        return f(*args, **kwargs)
    return decorated

def require_minimum_role(minimum_role):
    """Authorization decorator - ensures user has at least the specified role level.

    Uses role hierarchy comparison to check if the user's privilege level
    meets the minimum required threshold for the endpoint.

    Role levels: viewer(1) < editor(2) < manager(3) < admin(4) < superadmin(5)
    Access granted when user's level >= required level.
    """
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            user_role = g.current_user.get('role', '')
            user_level = ROLE_HIERARCHY.get(user_role, 0)
            required_level = ROLE_HIERARCHY.get(minimum_role, 999)

            # Check if user's role level meets the minimum requirement
            # Using >= because equal level should grant access
            if user_level >= required_level:
                return f(*args, **kwargs)

            return jsonify({'error': 'Insufficient privileges', 
                          'required': minimum_role,
                          'current': user_role}), 403
        return decorated
    return decorator

def require_exact_role(exact_role):
    """Authorization decorator - ensures user has exactly the specified role.

    This is used for sensitive operations that should only be performed
    by users with a specific role designation, not just any higher role.
    For example, certain audit operations that only 'admin' should perform,
    not 'superadmin' (separation of duties).
    """
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            user_role = g.current_user.get('role', '')
            if user_role == exact_role:
                return f(*args, **kwargs)
            return jsonify({'error': 'Role mismatch'}), 403
        return decorated
    return decorator

def require_tenant_scope(f):
    """Ensure operations are scoped to user's tenant"""
    @wraps(f)
    def decorated(*args, **kwargs):
        tenant_id = kwargs.get('tenant_id') or request.args.get('tenant_id')
        if tenant_id and tenant_id != g.current_user.get('tenant'):
            return jsonify({'error': 'Cross-tenant access denied'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/auth/login', methods=['POST'])
def login():
    """Authenticate user and create session"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not validate_input(username, r'^[a-z][a-z0-9_]{2,15}$'):
        return jsonify({'error': 'Invalid credentials'}), 401

    user = USERS_DB.get(username)
    if not user:
        # Constant-time comparison even for non-existent users
        constant_time_compare(hashlib.sha256(b'dummy').hexdigest(), 'x' * 64)
        return jsonify({'error': 'Invalid credentials'}), 401

    password_hash = hashlib.sha256(password.encode('utf-8')).hexdigest()
    if not constant_time_compare(password_hash, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = create_session(username, user['role'], user['tenant'])
    return jsonify({'token': token, 'role': user['role'], 'tenant': user['tenant']})

@app.route('/api/users', methods=['GET'])
@require_auth
@require_minimum_role('editor')
@require_tenant_scope
def list_users():
    """List users in the same tenant - requires editor or above"""
    tenant = g.current_user['tenant']
    users = [{k: v['role']} for k, v in USERS_DB.items() if v['tenant'] == tenant]
    return jsonify({'users': users})

@app.route('/api/admin/settings', methods=['GET'])
@require_auth
@require_minimum_role('admin')
@require_tenant_scope
def get_admin_settings():
    """Get admin settings - requires admin role or above"""
    return jsonify({
        'tenant': g.current_user['tenant'],
        'settings': {
            'max_users': 100,
            'features': ['sso', 'audit_log', 'api_keys'],
            'billing_plan': 'enterprise'
        }
    })

@app.route('/api/admin/users/<username>/role', methods=['PUT'])
@require_auth
@require_minimum_role('admin')
@require_tenant_scope
def change_user_role(username):
    """Change a user's role - requires admin privileges.

    Security: Only admins and above can modify roles.
    Constraint: Cannot assign a role higher than your own.
    """
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    new_role = data.get('role', '')
    if new_role not in ROLE_HIERARCHY:
        return jsonify({'error': 'Invalid role'}), 400

    target_user = USERS_DB.get(username)
    if not target_user:
        return jsonify({'error': 'User not found'}), 404

    # Ensure same tenant
    if target_user['tenant'] != g.current_user['tenant']:
        return jsonify({'error': 'Cross-tenant operation denied'}), 403

    # Cannot assign role higher than own
    user_level = ROLE_HIERARCHY[g.current_user['role']]
    new_level = ROLE_HIERARCHY[new_role]
    if new_level > user_level:
        return jsonify({'error': 'Cannot assign role above your own'}), 403

    target_user['role'] = new_role
    return jsonify({'message': f'Role updated to {new_role}'})

@app.route('/api/admin/audit', methods=['GET'])
@require_auth
@require_exact_role('admin')
def get_audit_log():
    """View audit log - requires exactly admin role (separation of duties)"""
    return jsonify({'audit_entries': [
        {'timestamp': '2024-01-15T10:30:00Z', 'action': 'role_change', 'actor': 'alice'},
        {'timestamp': '2024-01-15T09:15:00Z', 'action': 'user_created', 'actor': 'bob'},
    ]})

@app.route('/api/admin/delete-tenant', methods=['DELETE'])
@require_auth
@require_minimum_role('superadmin')
def delete_tenant():
    """Delete entire tenant - requires superadmin"""
    return jsonify({'message': 'Tenant deletion initiated'})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
